// Title: Hide rows generated by smart markers in an Aspose.Cells workbook when filtering by department using C#
// Common Searches: C# Aspose.Cells hide rows created by smart markers based on column value | How to hide non‑IT department rows after processing smart markers in Aspose.Cells | Filter smart marker output rows and hide them in C# Excel generation | Programmatically hide rows from smart marker expansion in Aspose.Cells | Aspose.Cells WorkbookDesigner hide rows that do not meet filter criteria
// Tags: smart marker row hiding Aspose.Cells C# | conditional row visibility after WorkbookDesigner | filter rows by column value Aspose.Cells | hide Excel rows generated by smart markers | Aspose.Cells hide rows based on data source criteria

using System;
using System.Data;
using Aspose.Cells;

namespace SmartMarkerRowHiding
{
    // The example creates a workbook, defines an Employees DataTable, inserts smart markers for Name, Department, and Salary, processes them with WorkbookDesigner, then iterates over the expanded rows and hides any row whose Department column is not "IT" before saving the file as SmartMarkerFilteredRows.xlsx.
    class Program
    {
        static void Main()
        {
            try
            {
                // Create a new workbook and get the first worksheet
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];
                sheet.Name = "Data";

                // Prepare a DataTable as the data source for smart markers
                DataTable dt = new DataTable("Employees");
                dt.Columns.Add("Name", typeof(string));
                dt.Columns.Add("Department", typeof(string));
                dt.Columns.Add("Salary", typeof(double));

                // Add sample rows
                dt.Rows.Add("John", "HR", 50000);
                dt.Rows.Add("Alice", "IT", 75000);
                dt.Rows.Add("Bob", "HR", 48000);
                dt.Rows.Add("Eve", "Finance", 62000);
                dt.Rows.Add("Mike", "IT", 71000);

                // Insert smart markers into the worksheet (starting at A1)
                // Header row
                sheet.Cells["A1"].PutValue("Name");
                sheet.Cells["B1"].PutValue("Department");
                sheet.Cells["C1"].PutValue("Salary");

                // Smart marker rows (will be expanded)
                sheet.Cells["A2"].PutValue("&=Employees.Name");
                sheet.Cells["B2"].PutValue("&=Employees.Department");
                sheet.Cells["C2"].PutValue("&=Employees.Salary");

                // Process smart markers using WorkbookDesigner
                WorkbookDesigner designer = new WorkbookDesigner(workbook);
                designer.SetDataSource(dt);
                designer.Process();

                // Hide rows where Department is not "IT"
                int firstDataRow = 1; // zero‑based index for the first data row (row 2 in Excel)
                int lastDataRow = sheet.Cells.MaxDataRow;
                for (int row = firstDataRow; row <= lastDataRow; row++)
                {
                    // Get the value from column B (Department)
                    string dept = sheet.Cells[row, 1].StringValue;
                    if (!string.Equals(dept, "IT", StringComparison.OrdinalIgnoreCase))
                    {
                        // Hide the entire row using the Row.IsHidden property
                        sheet.Cells.Rows[row].IsHidden = true;
                    }
                }

                // Save the workbook
                workbook.Save("SmartMarkerFilteredRows.xlsx");
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred: " + ex.Message);
            }
        }
    }
}
